<script>
	import { goto } from '$app/navigation';
	import FrameUpload from '$lib/components/FrameUpload.svelte';
	let characterImage = $state(null), drivingVideo = $state(null), drivingName = $state(''), videoInput;
	let isGenerating = $state(false), error = $state(''), videoUrl = $state(null), predictionId = $state(null), jobStatus = $state(''), elapsedSeconds = $state(0), startedAt = 0, timer;
	function chooseVideo(e) { const f = e.target.files?.[0]; if (!f?.type.startsWith('video/')) { error = 'Choose an MP4, MOV, or WebM video.'; return; } const r = new FileReader(); r.onload = () => { drivingVideo = r.result; drivingName = f.name; error = ''; }; r.readAsDataURL(f); }
	function startTimer() { if (timer) clearInterval(timer); startedAt = Date.now(); elapsedSeconds = 0; timer = setInterval(() => elapsedSeconds = Math.floor((Date.now() - startedAt) / 1000), 1000); }
	function stopTimer() { clearInterval(timer); timer = null; }
	function statusText() { return jobStatus === 'processing' ? 'Kling is transferring your performance...' : jobStatus === 'succeeded' ? 'Complete' : 'Kling is starting your job...'; }
	async function poll(id) { for (let i = 0; i < 240; i++) { await new Promise(r => setTimeout(r, 2500)); const res = await fetch(`/api/live-portrait?id=${encodeURIComponent(id)}`); const data = await res.json(); if (!res.ok) throw new Error(data.error || 'Could not check Kling status.'); jobStatus = data.status; if (data.status === 'succeeded') { videoUrl = data.videoUrl; return; } if (data.status === 'failed' || data.status === 'canceled') throw new Error(data.error || `Kling ${data.status}.`); } throw new Error('Kling is taking too long. Try a shorter video.'); }
	async function generate() { if (!characterImage || !drivingVideo || isGenerating) return; isGenerating = true; error = ''; videoUrl = null; predictionId = null; jobStatus = ''; startTimer(); try { const res = await fetch('/api/live-portrait', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ characterImage, drivingVideo }) }); const data = await res.json(); if (!res.ok) throw new Error(data.error || 'Kling request failed.'); predictionId = data.predictionId; jobStatus = data.status; await poll(predictionId); } catch (e) { error = e instanceof Error ? e.message : 'Kling request failed.'; } finally { isGenerating = false; stopTimer(); } }
</script>
<svelte:head><title>Kling Performance Motion - Sprite Magician</title></svelte:head>
<main class="min-h-screen bg-slate-50 text-slate-900"><header class="border-b bg-white"><div class="mx-auto flex max-w-5xl items-center justify-between px-5 py-3"><div><h1 class="text-lg font-bold">Sprite Magician</h1><p class="text-xs text-slate-500">Kling 3.0 motion transfer</p></div><button class="rounded border px-3 py-1.5 text-sm" onclick={() => goto('/')}>Back to workspace</button></div></header><section class="mx-auto max-w-5xl px-5 py-8"><p class="text-sm font-semibold text-violet-700">Performance Motion</p><h2 class="mt-1 text-3xl font-bold">Act it out. Your character copies it.</h2><p class="mt-2 text-sm text-slate-600">Upload a character image and a short video of yourself doing one action. Kling 3.0 transfers that motion to the character.</p><div class="mt-6 grid gap-5 lg:grid-cols-2"><section class="rounded-xl border bg-white p-5"><h3 class="font-bold">1. Character image</h3><div class="mt-3 h-64 bg-slate-100">{#if characterImage}<img src={characterImage} alt="Character" class="h-full w-full object-contain" />{:else}<FrameUpload label="Upload character bust" onUpload={(image) => characterImage = image} />{/if}</div>{#if characterImage}<button class="mt-3 text-sm text-violet-700" onclick={() => characterImage = null}>Choose another image</button>{/if}</section><section class="rounded-xl border bg-white p-5"><h3 class="font-bold">2. Your acted video</h3><input bind:this={videoInput} class="hidden" type="file" accept="video/mp4,video/quicktime,video/webm" onchange={chooseVideo} /><button class="mt-3 flex h-40 w-full flex-col items-center justify-center rounded-lg border-2 border-dashed" onclick={() => videoInput?.click()}><span class="text-sm font-semibold">{drivingName || 'Choose your performance clip'}</span><span class="mt-1 text-xs text-slate-500">MP4, MOV, or WebM · 3–10 seconds</span></button>{#if drivingVideo}<video class="mt-3 max-h-44 w-full bg-black" src={drivingVideo} controls muted></video>{/if}<p class="mt-3 text-xs text-slate-500">One person, fixed camera, same upper-body framing as the character, one clean action.</p></section></div><button class="mt-5 w-full rounded-lg bg-violet-600 px-4 py-3 font-bold text-white disabled:bg-slate-300" disabled={!characterImage || !drivingVideo || isGenerating} onclick={generate}>{isGenerating ? 'Transferring performance...' : 'Transfer performance with Kling 3.0'}</button>{#if error}<p class="mt-4 rounded border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>{/if}{#if isGenerating || predictionId}<div class="mt-4 rounded border border-violet-200 bg-violet-50 p-3"><b>{statusText()}</b><p class="text-xs">Elapsed: {elapsedSeconds}s{predictionId ? ` · Job ${predictionId}` : ''}</p></div>{/if}{#if videoUrl}<section class="mt-5 rounded-xl border bg-white p-5"><a class="text-sm text-violet-700" href={videoUrl} target="_blank" rel="noreferrer">Open / download</a><video class="mt-3 w-full bg-black" src={videoUrl} controls loop autoplay muted></video></section>{/if}</section></main>
